-- UNEXECUTED READ-ONLY PREFLIGHT. One deterministic catalog result.
WITH target AS (SELECT to_regclass('public.legal_policy_acceptances') AS relation_oid),
helper AS (SELECT count(*)=1 AND bool_and(pg_get_userbyid(p.proowner)='postgres' AND NOT p.prosecdef AND p.provolatile='v' AND p.proparallel='u' AND coalesce(cardinality(p.proconfig),0)=0 AND md5(regexp_replace(btrim(p.prosrc), '[[:space:]]+', ' ', 'g'))='077bb7aa35a4fed76f447b242607c205') AS exact FROM pg_proc p WHERE p.oid=to_regprocedure('public.set_updated_at()')),
roles AS (SELECT count(*)=4 AS exact FROM pg_roles WHERE rolname IN ('anon','authenticated','service_role','postgres')),
ledger AS (SELECT to_regclass('supabase_migrations.schema_migrations') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20260712') AS exact),
conflicts AS (SELECT EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname LIKE 'legal_policy_acceptances%') OR EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname LIKE 'record_current_legal_policy_acceptance%') AS present)
SELECT jsonb_build_object('packet_version','legal-consent-forward-only-preflight-v1','classification',CASE WHEN (SELECT relation_oid FROM target) IS NOT NULL OR (SELECT present FROM conflicts) THEN 'BLOCKED_PARTIAL_STATE' WHEN NOT (SELECT exact FROM helper) OR NOT (SELECT exact FROM roles) OR NOT (SELECT exact FROM ledger) OR to_regclass('auth.users') IS NULL OR to_regprocedure('gen_random_uuid()') IS NULL THEN 'BLOCKED_DEPENDENCY' ELSE 'SAFE_TO_CREATE_EXACTLY' END,'expected_object_count',52,'target_absent',(SELECT relation_oid IS NULL FROM target),'helper_exact',(SELECT exact FROM helper),'roles_exact',(SELECT exact FROM roles),'ledger_exact',(SELECT exact FROM ledger),'migration_ledger_unchanged_candidate',true) AS packet;
